#ifndef CHUNK_MANAGER_H
#define CHUNK_MANAGER_H

// World storage, chunk streaming, meshing and block access.
// main.c only talks to the world through this header; the Chunk struct is private.
// Terrain itself is generated by chunkGenerator.c.

#include <stdint.h>
#include <glad/gl.h>
#include "chunkGenerator.h"
#include "Lighting/lighting.h"   // LightHost

#define WORLD_FLOOR      0
#define RENDER_DISTANCE  16
#define WORLD_CHUNKS     ((RENDER_DISTANCE * 2) + 1)

// lifetime
void world_init(void);        // call after chunk_generator_set_seed()
void world_shutdown(void);    // frees every chunk's mesh + light data

// per frame
void world_load_around(double x, double z);     // streams in the closest missing chunks
void world_rebuild_meshes(double x, double z);  // remeshes dirty chunks (time budgeted)

// returns the number of triangles drawn
long world_draw(const float* vp, const float* cam_pos, GLuint chunk_prog,
    const GLuint* tex_ids, int tex_count);

// block access (world coordinates, outside the world counts as air)
int  world_in_bounds(int32_t x, int32_t y, int32_t z);
int  world_get_block(int32_t x, int32_t y, int32_t z);
int  world_block(int x, int y, int z);          // same as world_get_block, used by other modules
void world_set_block(int32_t x, int32_t y, int32_t z, int type);

// voxel DDA. hit = first solid block, prev = empty cell before it (where a block gets placed)
int  world_raycast(const float* origin, const float* dir, float max_dist, int* hit, int* prev);

// y a player can stand at for column (bx, bz). The column's chunk must be loaded.
int  world_spawn_height(int bx, int bz);

// lighting.c reaches the world through this
const LightHost* world_light_host(void);

#endif